package cn.hydrogen.launcher;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.lang.reflect.*;
/** Modes and seeks verified against original QQ update_state broadcasts, never synthetic replies. */
final class QqPlaybackAuditFlow {
 private final Instrumentation test;private final StringBuilder report=new StringBuilder("Actual embedded QQ mode and seek audit\n");private int passed;private volatile long rawAt,rawPosition=-1;private final java.util.List<String> trace=java.util.Collections.synchronizedList(new java.util.ArrayList<>());private QqMusicBridge bridge;
 QqPlaybackAuditFlow(Instrumentation t){test=t;}interface Condition{boolean get()throws Exception;}
 private void main(Runnable r){Throwable[] e={null};test.runOnMainSync(()->{try{r.run();}catch(Throwable p){e[0]=p;}});if(e[0]!=null)throw new AssertionError(e[0]);}
 private void check(boolean ok,String label){if(!ok)throw new AssertionError(label);passed++;report.append("PASS ").append(label).append('\n');}
 private void await(String label,Condition c,long ms)throws Exception{long until=SystemClock.elapsedRealtime()+ms;while(!c.get()&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);check(c.get(),label);}
 private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 void run(){Context app=test.getTargetContext();Bundle result=new Bundle();boolean ok=false,registered=false;int original=0;BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){try{JSONObject root=new JSONObject(i.getStringExtra(QqMusicBridge.EXTRA));JSONObject cmd=root.optJSONObject("command"),data=cmd==null?null:cmd.optJSONObject("data");if(cmd!=null&&data!=null&&"update_state".equals(cmd.optString("method"))&&data.has("curr_time")){rawPosition=data.getLong("curr_time");rawAt=SystemClock.elapsedRealtime();if(trace.size()<100)trace.add(rawAt+" state="+data.optInt("state",-1)+" pos="+rawPosition);}}catch(Exception ignored){}}};
 try{main(()->{if(Build.VERSION.SDK_INT>=33)app.registerReceiver(receiver,new IntentFilter(QqMusicBridge.EVENTS),Context.RECEIVER_EXPORTED);else app.registerReceiver(receiver,new IntentFilter(QqMusicBridge.EVENTS));});registered=true;
 MainActivity home=(MainActivity)test.startActivitySync(new Intent(app,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));main(()->home.showPage(MainActivity.CARDS));bridge=(QqMusicBridge)field(home,"musicBridge");main(bridge::subscribe);await("selected track has a real QQ snapshot",()->bridge.connected&&bridge.trackConfirmed&&bridge.duration>60000,20000);original=bridge.playMode;
 for(int desired:new int[]{QqMusicBridge.SINGLE,QqMusicBridge.SHUFFLE,QqMusicBridge.ORDER}){main(()->bridge.setMode(desired));await("native mode ACK "+desired,()->bridge.playMode==desired&&bridge.pendingMode==0,7000);}
 long basePosition=rawPosition;main(()->bridge.command(0));await("native playback established before pause",()->bridge.state==2,15000);await("original native playback position advances",()->rawPosition>basePosition+600,15000);Thread.sleep(1200);main(()->bridge.command(1));await("native pause before seek",()->bridge.state==3,10000);Thread.sleep(2200);
 long before=bridge.currentPosition();long target=before<bridge.duration/2?bridge.duration*3/5:bridge.duration/4;long requested=SystemClock.elapsedRealtime();int track=bridge.trackRevision;main(()->check(bridge.seekTo(target,track),"production relative seek issued"));
 await("original native state confirms actual seek target",()->rawAt>=requested&&Math.abs(rawPosition-target)<3500,12000);main(()->bridge.command(1));await("native pause after relative seek",()->bridge.state==3,10000);Thread.sleep(3000);long held=bridge.currentPosition();check(Math.abs(held-target)<6000,"desktop follows confirmed target");Thread.sleep(9200);main(bridge::subscribe);Thread.sleep(1300);check(bridge.state==3&&Math.abs(bridge.currentPosition()-held)<2200,"seek does not roll back after old-sample guard expires");check(rawPosition>=0&&Math.abs(bridge.currentPosition()-rawPosition)<2200,"desktop and latest original native position agree");ok=true;
 }catch(Throwable e){report.append("FAIL state=").append(bridge==null?-1:bridge.state).append(" ").append(e).append('\n');}finally{if(bridge!=null&&QqMusicBridge.validMode(original)){final int restore=original;main(()->bridge.setMode(restore));}if(registered)main(()->app.unregisterReceiver(receiver));}
 synchronized(trace){for(String line:trace)report.append("NATIVE ").append(line).append("\n");}report.append("QQ_PLAYBACK_AUDIT_RESULT checks=").append(passed).append(ok?" PASS":" FAIL").append('\n');result.putString("stream",report.toString());test.finish(ok?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
